// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address receiver, uint256 amount) public {
        vm.assume(receiver != address(0));
        vm.assume(amount > 0);

        // Ensure the contract starts unpaused
        assertTrue(!c.paused(), "Contract should start unpaused");

        // Record paused state before claim
        bool pausedBefore = c.paused();

        // Attempt to execute claim
        (bool success, bytes memory data) = address(c).call(
            abi.encodeWithSelector(c.claim.selector, receiver, amount)
        );

        // Record paused state after claim
        bool pausedAfter = c.paused();

        // General rule: If contract was unpaused before, the claim should succeed and paused state unchanged
        assertTrue(!pausedBefore || (success && pausedAfter == pausedBefore), "Rule violated");
    }
}

